print(f"Total slides: {len(prs.slides)}")
print("=" * 80)

for i, slide in enumerate(prs.slides):
    print(f"\n--- Slide {i+1} ---")
    print(f"  Layout: {slide.slide_layout.name}")
    for j, shape in enumerate(slide.shapes):
        print(f"  Shape {j}: name='{shape.name}', type={shape.shape_type}, "
              f"left={shape.left}, top={shape.top}, width={shape.width}, height={shape.height}")
        if shape.has_text_frame:
            for k, para in enumerate(shape.text_frame.paragraphs):
                text = para.text.strip()
                if text:
                    runs_info = []
                    for run in para.runs:
                        font = run.font
                        try:
                            color_rgb = str(font.color.rgb) if font.color and font.color.type is not None else None
                        except:
                            color_rgb = None
                        runs_info.append({
                            'text': run.text,
                            'bold': font.bold,
                            'size': str(font.size) if font.size else None,
                            'color': color_rgb,
                            'font_name': font.name,
                        })
                    if len(text) > 100:
                        print(f"    Para {k}: '{text[:100]}...'")
                    else:
                        print(f"    Para {k}: '{text}'")
                    for ri in runs_info:
                        print(f"      Run: {ri}")
